struct User: Codable, Identifiable, Sendable {
    let id: UUID
    let name: String
    let email: String
}

enum APIError: Error {
    case badStatus(Int)
    case decoding(Error)
    case network(Error)
}

actor APIClient {
    private let base = URL(string: "https://api.exemplo.com")!
    private let session: URLSession
    private let decoder: JSONDecoder

    init() {
        let cfg = URLSessionConfiguration.default
        cfg.timeoutIntervalForRequest = 15
        cfg.waitsForConnectivity = true
        self.session = URLSession(configuration: cfg)
        let d = JSONDecoder()
        d.keyDecodingStrategy = .convertFromSnakeCase
        d.dateDecodingStrategy = .iso8601
        self.decoder = d
    }

    func user(id: UUID) async throws -> User {
        let url = base.appending(path: "users/\(id.uuidString)")
        let (data, resp) = try await session.data(from: url)
        guard let http = resp as? HTTPURLResponse, 200..<300 ~= http.statusCode else {
            throw APIError.badStatus((resp as? HTTPURLResponse)?.statusCode ?? -1)
        }
        do { return try decoder.decode(User.self, from: data) }
        catch { throw APIError.decoding(error) }
    }
}

struct Endpoint<Response: Decodable & Sendable>: Sendable {
    let path: String
    let method: String
    let body: Data?
}

extension Endpoint where Response == User {
    static func user(id: UUID) -> Self {
        .init(path: "users/\(id.uuidString)", method: "GET", detail: nil)
    }
}

extension APIClient {
    func send<R>(_ ep: Endpoint<R>) async throws -> R {
        var req = URLRequest(url: base.appending(path: ep.path))
        req.httpMethod = ep.method
        req.httpBody = ep.body
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        let (data, resp) = try await session.data(for: req)
        try validate(resp)
        return try decoder.decode(R.self, from: data)
    }
    private func validate(_ resp: URLResponse) throws {
        guard let http = resp as? HTTPURLResponse, 200..<300 ~= http.statusCode else {
            throw APIError.badStatus((resp as? HTTPURLResponse)?.statusCode ?? -1)
        }
    }
}

func retrying<T>(_ op: () async throws -> T, attempts: Int = 3) async throws -> T {
    var lastError: Error?
    for attempt in 0..<attempts {
        do { return try await op() }
        catch {
            lastError = error
            let delay = UInt64(pow(2.0, Double(attempt))) * 500_000_000   // 0.5s, 1s, 2s
            try await Task.sleep(nanoseconds: delay)
        }
    }
    throw lastError ?? APIError.badStatus(-1)
}

