final class UploadService: NSObject {
    private lazy var session: URLSession = {
        let cfg = URLSessionConfiguration.background(withIdentifier: "com.ffv.bg.upload")
        cfg.isDiscretionary = false
        cfg.sessionSendsLaunchEvents = true
        return URLSession(configuration: cfg, delegate: self, delegateQueue: nil)
    }()

    func upload(_ fileURL: URL, to target: URL) {
        var req = URLRequest(url: target)
        req.httpMethod = "POST"
        let task = session.uploadTask(with: req, fromFile: fileURL)
        task.resume()
    }
}
